package com.trekmate.service;
import com.fasterxml.jackson.databind.JsonNode; import com.trekmate.dto.WeatherResponse; import com.trekmate.entity.Trek; import com.trekmate.exception.NotFoundException; import com.trekmate.repository.TrekRepository; import java.math.BigDecimal; import java.time.*; import java.util.concurrent.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@Service public class OpenWeatherService implements WeatherService { private record Cached(WeatherResponse value, Instant expiresAt){} private final TrekRepository treks; private final RestClient client; private final String key; private final ConcurrentMap<Long,Cached> cache=new ConcurrentHashMap<>(); public OpenWeatherService(TrekRepository treks,RestClient.Builder builder,@Value("${app.openweather.base-url}") String url,@Value("${app.openweather.api-key}") String key){this.treks=treks;this.client=builder.baseUrl(url).build();this.key=key;} public WeatherResponse getCurrentWeather(Long id){Cached c=cache.get(id);if(c!=null&&c.expiresAt().isAfter(Instant.now()))return c.value();if(key.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"OpenWeather API key is not configured.");Trek t=treks.findById(id).orElseThrow(()->new NotFoundException("Trek not found."));JsonNode b=client.get().uri(u->u.path("/weather").queryParam("lat",t.getLatitude()).queryParam("lon",t.getLongitude()).queryParam("appid",key).queryParam("units","metric").build()).retrieve().body(JsonNode.class);WeatherResponse r=new WeatherResponse(b.path("main").path("temp").decimalValue(),b.path("main").path("humidity").asInt(),b.path("wind").path("speed").decimalValue(),b.path("rain").has("1h")?b.path("rain").path("1h").decimalValue().multiply(BigDecimal.valueOf(100)):BigDecimal.ZERO,b.path("weather").path(0).path("icon").asText());cache.put(id,new Cached(r,Instant.now().plus(Duration.ofMinutes(15))));return r;} }
